 static int passed,failed;
 static void Check(bool condition,string name){if(!condition)throw new Exception(name);passed++;}
 static void Eq<T>(T actual,T expected,string name)=>Check(EqualityComparer<T>.Default.Equals(actual,expected),name);
 static T Field<T>(object o,string name)=>(T)o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);
 static void Case(string name,Action body){try{Reset();body();Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.GetBaseException().Message);}}
 static PlayerControl P(byte id,CustomRoles role=CustomRoles.Crewmate,int? client=null){var p=new PlayerControl{PlayerId=id,NetId=(uint)(100+id),ClientId=client??(10+id),Role=role,Data=new(){PlayerId=id,NetId=(uint)(200+id)}};PlayerCatch.Players[id]=p;Camouflage.PlayerSkins[id]=new(){ColorId=id};return p;}
 static void Reset(){AmongUsClient.Instance=new();PlayerCatch.Players.Clear();CustomRoleManager.AllActiveRoles.Clear();CustomRoleManager.RoleSends.Clear();PetActionManager.Actions.Clear();Camouflage.PlayerSkins.Clear();Camouflage.IsCamouflage=false;CustomRpcSender.Sent.Clear();Utils.Messages.Clear();Logger.Logs.Clear();LateTask.Pending.Clear();RoleManager.Instance=new();GameStates.InGame=GameStates.IsInGame=GameStates.IsInTask=true;GameStates.IsMeeting=GameStates.CalledMeeting=GameStates.Intro=false;Time.time=100;Time.fixedDeltaTime=.02f;PlayerControl.LocalPlayer=P(0);Framer.ResetEffects();NameRpcBatch.Clear();TestOptions.All.Clear();SoloWinOption.AllData.Clear();foreach(var info in new[]{MadKind.RoleInfo,Framer.RoleInfo,NiceHacker.RoleInfo,Romeo.RoleInfo}) info.OptionCreator();CustomWinnerHolder.Reset();AdminProvider.Entries.Clear();TownOfHost.Roles.AddOns.Common.Amnesia.Blocked=false;Sheriff.StartInTaskMode.Value=0;}
 static void Opt(CustomRoles role,string name,float value)=>TestOptions.All[(role,name)].Value=value;
 static (Romeo,Juliet,PlayerControl,PlayerControl) Pair(){var p=P(1);var q=P(2);var r=new Romeo(p);var j=new Juliet(q);r.Add();j.Add();return(r,j,p,q);}
 static void Press(Framer role){bool adjust=true;bool? cooldown=null;role.OnClick(ref adjust,ref cooldown);}
 static (Framer,PlayerControl,PlayerControl) Frame(byte id=1){var p=P(id);var source=P(5);var target=P(6);var f=new Framer(p);f.Add();f.SingleAction(p,source);p.Target=target;return(f,p,target);}
 static MethodInfo Patch(Type type,string name,string method)=>type.GetNestedType(name,BindingFlags.NonPublic).GetMethod(method,BindingFlags.Public|BindingFlags.Static);
 static byte[] Packet(SendOption option,int count,int size=400,byte tag=6){var w=MessageWriter.Get(option);w.StartMessage(tag);w.Write(100);if(tag==6)w.WritePacked(17);for(int i=0;i<count;i++){w.StartMessage(2);w.Write(Enumerable.Repeat((byte)(i+1),size).ToArray());w.EndMessage();}w.EndMessage();return w.ToByteArray(true);}
 static List<byte[]> Children(byte[] bytes,int header){var result=new List<byte[]>();int p=header;while(p<bytes.Length){int len=bytes[p]|bytes[p+1]<<8;byte tag=bytes[p+2];int end=p+3+len;int c=p+7;if(tag==6){while((bytes[c++]&128)!=0){}}while(c<end){int n=3+bytes[c]+(bytes[c+1]<<8);result.Add(bytes.Skip(c).Take(n).ToArray());c+=n;}p=end;}return result;}
 static byte[] WithHeader(byte[] body,int header)=>new byte[header].Concat(body).ToArray();
 static bool Split(MessageWriter writer,bool original=true)=>(bool)Patch(typeof(NetworkSafety),"SplitPatch","Prefix").Invoke(null,new object[]{AmongUsClient.Instance,writer,original});
 static string Json(string name="TownOfHost-Shell.dll",string url="https://github.com/sijimi2222/TownOfHost-Shell/releases/download/v2.2.0-beta.1/TownOfHost-Shell.dll",string tag="v2.2.0-beta.1")=>JsonSerializer.Serialize(new{tag_name=tag,body="notes",assets=new[]{new{name,browser_download_url=url}}});
