 Case("release JSON and repository bounds",()=>{Check(ShellReleaseMetadata.TryRead(Json(),"Steam",out var latest),"generic asset valid");Eq(latest.Version,new Version(2,2,0),"beta tag version");Eq(latest.Body,"notes","body preserved");Check(ShellReleaseMetadata.ParseVersion("v2.2.0β")!=null,"unicode beta");Check(!ShellReleaseMetadata.TryRead("{", "Steam",out _),"malformed JSON safe");Check(!ShellReleaseMetadata.TryRead("[]","Steam",out _),"wrong root safe");Check(!ShellReleaseMetadata.TryRead(Json(tag:"invalid"),"Steam",out _),"invalid version rejected");Check(!ShellReleaseMetadata.TryRead(Json(url:"https://github.com/rar006/TownOfHost-hamo/releases/download/v4/a.dll"),"Steam",out _),"hamo update not selected");Check(!ShellReleaseMetadata.TryRead(Json(url:"http://github.com/sijimi2222/TownOfHost-Shell/releases/download/v/a.dll"),"Steam",out _),"HTTP rejected");Check(!ShellReleaseMetadata.TryRead(Json(url:"https://github.com.evil.invalid/sijimi2222/TownOfHost-Shell/releases/download/v/a.dll"),"Steam",out _),"lookalike host rejected");var data=JsonSerializer.Serialize(new{tag_name="v2.3.0",assets=new[]{new{name="TownOfHost-Shell.dll",browser_download_url="https://github.com/sijimi2222/TownOfHost-Shell/releases/download/v2.3.0/generic.dll"},new{name="TownOfHost-Shell_Steam.dll",browser_download_url="https://github.com/sijimi2222/TownOfHost-Shell/releases/download/v2.3.0/steam.dll"}}});Check(ShellReleaseMetadata.TryRead(data,"Steam",out latest)&&latest.DownloadUrl.EndsWith("steam.dll"),"platform asset preferred");});
 Case("statistics startup is non-destructive",()=>{string dir=Path.Combine(Path.GetTempPath(),"toh-statistics-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{string file=Path.Combine(dir,"current"),legacy=Path.Combine(dir,"legacy");File.WriteAllText(file,"current fixture");File.WriteAllText(legacy,"legacy fixture");StatisticsStore.EnsureExists(file,legacy);Eq(File.ReadAllText(file),"current fixture","existing data kept");string migrated=Path.Combine(dir,"sub","migrated");StatisticsStore.EnsureExists(migrated,legacy);Eq(File.ReadAllText(migrated),"legacy fixture","migration copies");Eq(File.ReadAllText(legacy),"legacy fixture","legacy unchanged");string empty=Path.Combine(dir,"empty");StatisticsStore.EnsureExists(empty,null);Eq(new FileInfo(empty).Length,0L,"new store empty");}finally{Directory.Delete(dir,true);}});
 Case("managed news and beta metadata parsing",()=>{Check(ShellJsonData.TryReadNews("{\"News\":[{\"Number\":1,\"Title\":\"fixture\"},{\"Number\":\"2\",\"Body\":\"sample\"},{\"Number\":1},{\"Number\":{}},null]}",out var rows),"news valid");Eq(rows.Count,2,"invalid and duplicate records ignored");Eq(rows[0].Title,"fixture","title retained");Eq(rows[1].Number,2,"numeric string supported");Check(!ShellJsonData.TryReadNews("{\"News\":{}}",out _),"wrong news shape");Check(!ShellJsonData.TryReadNews("{",out _),"malformed news safe");Check(ShellJsonData.TryReadBeta("{\"name\":\"fixture\",\"url\":\"https://example.invalid/beta.dll\",\"body\":\"notes\"}",out var name,out var url,out var body)&&name=="fixture"&&body=="notes","beta schema retained");Check(!ShellJsonData.TryReadBeta("[]",out _,out _,out _),"beta wrong root");Check(!ShellJsonData.TryReadBeta("{\"name\":7}",out _,out _,out _),"beta invalid fields");});
 Case("assignment budgets guarantee, capacity, inverted limits",()=>{var min=new Dictionary<CustomRoleTypes,int>{{CustomRoleTypes.Crewmate,0},{CustomRoleTypes.Neutral,0},{CustomRoleTypes.Madmate,0}};var max=new Dictionary<CustomRoleTypes,int>{{CustomRoleTypes.Crewmate,10},{CustomRoleTypes.Neutral,10},{CustomRoleTypes.Madmate,10}};var cap=new Dictionary<CustomRoleTypes,int>{{CustomRoleTypes.Crewmate,8},{CustomRoleTypes.Neutral,2},{CustomRoleTypes.Madmate,0}};var sure=new Dictionary<CustomRoleTypes,int>{{CustomRoleTypes.Neutral,2}};var counts=RoleAssignmentBudget.Others(10,min,max,cap,sure,n=>0);Eq(counts.Values.Sum(),10,"fill available seats");Eq(counts[CustomRoleTypes.Neutral],2,"paired guaranteed seats");Eq(counts[CustomRoleTypes.Madmate],0,"zero capacity cannot consume seat");counts=RoleAssignmentBudget.Others(2,min,max,cap,sure,n=>0);Eq(counts[CustomRoleTypes.Neutral],2,"guaranteed precedes ordinary");min[CustomRoleTypes.Crewmate]=8;max[CustomRoleTypes.Crewmate]=1;counts=RoleAssignmentBudget.Others(5,min,max,cap,sure,n=>0);Check(counts.Values.Sum()<=5,"inverted limits bounded");counts=RoleAssignmentBudget.Others(0,min,max,cap,sure,n=>0);Eq(counts.Values.Sum(),0,"zero seats");counts=RoleAssignmentBudget.Others(3,min,max,new Dictionary<CustomRoleTypes,int>(),sure,n=>0);Eq(counts.Values.Sum(),0,"no candidates no invented roles");});
 Case("blacklist JSON preserves identity category and reason fields",()=>{var json="{\"blockedPlayers\":[{\"FriendCode\":\"synthetic-code\",\"AddedMod\":\"fixture\",\"Reason\":{\"Code\":\"fixture-reason\",\"Title\":\"sample\",\"Description\":\"fixture\"},\"EndBanTime\":\"never\"}],\"blockedPlayersPUID\":[{\"PUID\":\"synthetic-puid\",\"EndBanTime\":\"2030-01-01\"}]}";Check(ShellJsonData.TryReadBlacklist(json,out var rows),"schema accepted");Eq(rows.Count,2,"both categories");Check(!rows[0].IsPUID&&rows[1].IsPUID,"identifier categories unchanged");Eq(rows[0].Code,"synthetic-code","code field retained");Eq(rows[1].Code,"synthetic-puid","puid field retained");Eq(rows[0].ReasonCode,"fixture-reason","nested reason");Eq(rows[0].EndBanTime,"never","unlimited expiry marker");Check(!ShellJsonData.TryReadBlacklist("{\"blockedPlayers\":[]}",out rows)&&rows.Count==0,"partial schema rejected without partial data");Check(!ShellJsonData.TryReadBlacklist("{",out rows)&&rows.Count==0,"malformed JSON safe");Check(ShellJsonData.TryReadBlacklist("{\"blockedPlayers\":[],\"blockedPlayersPUID\":[]}",out rows)&&rows.Count==0,"empty list valid");Check(!Logger.Logs.Any(x=>x.Contains("synthetic-code")||x.Contains("synthetic-puid")),"identifiers not logged");});
 Console.WriteLine($"Assertions passed: {passed}; failed scenarios: {failed}");Environment.ExitCode=failed==0?0:1;
 }
